function normProv(s) {
  if (s === undefined || s === null) return '';
  return String(s)
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toUpperCase().replace(/[\/\-]/g, ' ')
    .replace(/\s+/g, ' ').trim();
}

// Devuelve {codigo, nombre} de una provincia ESPAÑOLA, o null si no la reconoce.
// NULL no es un error: casi siempre significa que el nacimiento fue en el
// extranjero, y entonces el llamante pone codigo '00' y copia el nombre tal cual.
function provinciaEspanola(texto) {
  const k = normProv(texto);
  if (!k) return null;
  const cod = PROV_CODIGO[k];
  if (!cod) return null;
  return { codigo: cod, nombre: PROV_NOMBRE[cod] };
}

// ── AVISO PARA QUIEN CONSTRUYA EL GENERADOR ───────────────────────────────────
// NULL NO SIGNIFICA "EXTRANJERO". Significa "no lo reconozco".
//
// El campo de provincia de nacimiento lo teclea una persona en la conversacion, y
// esta tabla cubre 97 formas de escribirlo pero NO TODAS. En la prueba del 13/08,
// 'Sta Cruz de Tenerife' devolvio null aunque 'Tenerife' y 'Santa Cruz de
// Tenerife' si funcionan.
//
// Si el generador trata ese null como "extranjero" y emite codigo '00' junto a un
// nombre de provincia ESPAÑOLA, sale una declaracion mal presentada y nadie se
// entera: el fichero se genera, la sede lo acepta y el error viaja hasta Hacienda.
//
// LA REGLA CORRECTA, y hay que implementarla asi:
//   pais de nacimiento == 'ESPAÑA'  y  provinciaEspanola() == null
//        -> NO GENERAR el .030. Parar y avisar.
//   pais de nacimiento != 'ESPAÑA'
//        -> codigo '00' y el nombre copiado tal cual, como en las muestras
//           ('00RABAT', '00MARACAY').
//
// Es el mismo criterio que paisISO(): antes que rellenar a medias un fichero que
// va a Hacienda, se para.

// ==================== tabla-municipios-ine-2026-08-14.js ====================
// ============================================================================
// CODIGOS INE DE MUNICIPIO · para el fichero .030 · 14/08/2026
// ----------------------------------------------------------------------------
// FUENTE: INE, "Relacion de municipios y codigos por comunidades autonomas y
// provincias a 1 de enero de 2026" (diccionario26.xlsx), descargado el 14/08/2026.
// 8.132 municipios.
//
// PARA QUE SIRVE: el .030 lleva el codigo INE del municipio en dos sitios,
// posiciones 369-373 (municipio de NACIMIENTO) y 865-869 (municipio de
// RESIDENCIA). El de residencia va relleno SIEMPRE en las cuatro muestras
// reales y no es opcional. El codigo son CINCO digitos: provincia(2)+municipio(3).
//
// POR QUE HAY QUE PASARLE LA PROVINCIA: 64 nombres de municipio existen en mas
// de una provincia (hay Villanueva y Villaverde por toda Espana). Sin provincia
// la busqueda seria una moneda al aire. La provincia sale gratis: son los DOS
// PRIMEROS DIGITOS DEL CODIGO POSTAL, que ya se le pide al cliente.
//
// LA Ñ NO SE MACHACA. Si se convierte en N, en Granada 'El Pinar' (910) y
// 'Piñar' (159) se convierten en el mismo municipio. Es el unico choque de los
// 9.620 y desaparece conservando la Ñ. Los demas acentos si se quitan, porque
// el cliente escribe 'Valencia' y el INE dice 'Valencia' con acento abierto.
//
// ALIAS INCLUIDOS: los nombres con el articulo detras ('Iglesuela del Cid, La')
// entran ademas como 'La Iglesuela del Cid' y como 'Iglesuela del Cid'; y los
// bilingues con barra ('Agurain/Salvatierra', 'Donostia/San Sebastian') entran
// por las dos mitades. 9.620 claves para 8.132 municipios.
//
// COMPROBADO CONTRA LOS FICHEROS .030 REALES:
//   TARRAGONA/43 -> 148 · MADRID/28 -> 079 · VALENCIA/46 -> 250
//   BARCELONA/08 -> 019 · BENICARLO/12 -> 027      (las cinco, correctas)
//
// ---------------------------------------------------------------------------
// NULL NO SIGNIFICA "NO EXISTE". Significa "NO LO RECONOZCO", y entonces
// NO SE GENERA EL .030: se para y se avisa. Nunca se rellena con ceros: un
// codigo INE inventado manda el expediente a otro municipio y el fichero se
// acepta igual, asi que nadie se entera hasta que vuelve rechazado.
// ---------------------------------------------------------------------------

// Normaliza como se normalizo la tabla: mayusculas, sin acentos (salvo la Ñ),
// sin espacios ni puntuacion. 'La Roda de Andalucia' y 'RODA DE ANDALUCIA, LA'
// acaban en la misma clave.
function normalizarMunicipio(texto) {
  if (texto == null) return '';
  return String(texto)
    .replace(/[Ññ]/g, '\u0001')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/\u0001/g, 'Ñ')
    .toUpperCase()
    .replace(/[^A-Z0-9Ñ]/g, '');
}

